def check_parameter_effect(global_var, data, W, X_m_init_vect_list, check_acc=None):
    """
    Plot the total distance between U and Q' while changing the value of a parameter.

    return:
        save: list[dict[Any, Any]]
    """
    parameter = global_var["parameter"]
    val = global_var["val"]

    cmap = plt.get_cmap('plasma')
    save = []

    color = list(np.linspace(0, 1, len(val)))
    for i in range(len(val)):

        data_copy = deepcopy(data)
        global_var[parameter] = val[i]
        decentralized_PCA(global_var, data_copy, W, X_m_init_vect_list)

        print(f"\n\n{parameter} = {global_var[parameter]}")
        if check_acc is not None:
            check_accuracy(global_var, data_copy, [10**-i for i in range(1, check_acc+1)])
        print(np.mean(data_copy["TY"]), np.mean(data_copy["TZ"]), len(data_copy[1]["U"])-1)
        plot(global_var, data_copy, None, None, show=False, label=f"{parameter} = {global_var[parameter]}", color=cmap(color[i]))
        save.append(data_copy)

    plt.title(label=f"Evolution of the distance between U = (u1 ... uP) and Q' = (q1 ... qP)")
    plt.xlabel(xlabel="t")
    plt.ylabel(ylabel=f"Distance between U and Q")

    plt.ylim(0)
    plt.legend(fontsize='small', bbox_to_anchor=(1.05, 1), ncol=len(val)//20+1)
    plt.show()

    return save



def replot(global_var, save, ylim=None):
    """
    Replot every saved data dictionnary without computing again.

    return:
        None
    """
    parameter = global_var["parameter"]
    val = global_var["val"]

    cmap = plt.get_cmap('plasma')
    color = np.linspace(0, 1, len(val))
    for i in range(len(val)):
        global_var[parameter] = val[i]
        plot(global_var, save[i], None, None, show=False, label=f"{parameter} = {global_var[parameter]}", color=cmap(color[i]))

    plt.title(label=f"Evolution of the distance between U = (u1 ... uP) and Q' = (q1 ... qP)")
    plt.xlabel(xlabel="t")
    plt.ylabel(ylabel=f"Distance between U and Q")

    plt.ylim(0, ylim)
    plt.legend(fontsize='small', bbox_to_anchor=(1.05, 1), ncol=len(val)//20+1)
    plt.show()



def convergence_table(axTY, axTZ, T, add_title=None):
    """
    Display a table of the number of iterations needed depending on the variables T_Y and T_Z.

    return:
        None
    """

    #Two axes : table, colorbar
    fig, (ax, cax) = plt.subplots(
        2, 1,
        figsize=(11.69, 8.27*0.95),
        gridspec_kw={"height_ratios": [35, 0.5]},
        constrained_layout=True,
        dpi=1000
    )
    
    fig.suptitle(
        f"Number of iterations needed (Total, T_PM, avg(T_Y), avg(T_Z)){" | "+add_title if add_title is not None else ""}",
        fontsize=12,
        fontweight="bold",
        x=0.5,
        y=0.93
    )

    ax.axis("off")
    ax.set_position([0.05, 0.13, 0.90, 0.75])
    cax.set_position([0.025, 0.08, 0.90, 0.02])

    T_total = np.array([[tpm*(1+ty_bar+tz_bar) for tpm,ty_bar,tz_bar in row] for row in T])
    T_total = T_total.T

    cell_text = np.array([[f"{tpm*(1+ty_bar+tz_bar):.0f}\n{tpm:.0f}| {ty_bar:.0f}| {tz_bar:.0f}" for tpm,ty_bar,tz_bar in row] for row in T], dtype=object)
    cell_text = cell_text.T

    table = ax.table(
        cellText=cell_text.tolist(),
        rowLabels=[str(z) for z in axTZ],
        colLabels=[str(y) for y in axTY],
        loc="center",
        cellLoc="center"
    )

    table.auto_set_font_size(False)
    table.set_fontsize(4)

    #Colormap
    norm = Normalize(vmin=np.min(T_total[T_total!=0]), vmax=T_total.max())
    cmap = plt.get_cmap("Blues")

    #Cells color
    for i in range(T_total.shape[0]):
        for j in range(T_total.shape[1]):
            cell = table[(i+1, j)]

            if T_total[i, j] == 0:
                cell.set_facecolor("black")
                cell.get_text().set_color("white")
            else:
                cell.set_facecolor(cmap(norm(T_total[i, j])))
                cell.get_text().set_color("white" if norm(T_total[i, j]) > 0.5 else "black")

    #Header
    for j in range(len(axTY)):
        table[(0, j)].set_facecolor("lightgray")
        table[(0, j)].get_text().set_weight("bold")
        table[(0, j)].set_fontsize(8)

    for i in range(len(axTZ)):
        table[(i+1, -1)].set_facecolor("lightgray")
        table[(i+1, -1)].get_text().set_weight("bold")
        table[(i+1, -1)].set_fontsize(8)

    i_min, j_min = np.argwhere(T_total == np.min(T_total[T_total!=0]))[0]
    table[(0, j_min)].set_facecolor("lightgreen")
    table[(i_min+1, -1)].set_facecolor("lightgreen")

    #Add upper left header cell
    header = table.add_cell(
        0, -1,
        width=table[(1, -1)].get_width(),
        height=table[(0, 0)].get_height(),
        text="T_Z \\ T_Y",
        loc="center"
    )
    header.set_facecolor("lightgray")
    header.get_text().set_weight("bold")
    header.set_fontsize(8)

    #Colorbar
    sm = cm.ScalarMappable(norm=norm, cmap=cmap)
    sm.set_array([])
    fig.colorbar(sm, cax=cax, orientation="horizontal", label="Value")

    plt.show()



def get_convergence_values(global_var, data, W, X_m_init_vect_list, axTY, axTZ, verb=True):
    """
    Display a table of the number of iterations needed depending on the variables T_Y and T_Z.

    return:
        T: list[list[list[float]]]
    """

    T = np.zeros((len(axTY), len(axTZ)), dtype=object)

    for i_y in range(len(axTY)):
        global_var["T_Y"] = axTY[i_y]

        for i_z in range(len(axTZ)):
            global_var["T_Z"] = axTZ[i_z]

            data_copy = deepcopy(data)
            tpm = decentralized_PCA(global_var, data_copy, W, X_m_init_vect_list)
            ty_bar, tz_bar = (np.mean(data_copy["TY"]), np.mean(data_copy["TZ"]))
            T[i_y, i_z] = [tpm, ty_bar, tz_bar]

            if verb:
                print(f"T_Y={global_var["T_Y"]}: {ty_bar}")
                print(f"T_Z={global_var["T_Z"]}: {tz_bar}")
                print(f"T_PM={global_var["T_PM"]}: {T[i_y, i_z][0] if T[i_y, i_z][0] else global_var["T_PM"]}")
                print()

            del data_copy

    if verb:
        print(np.array(T.tolist()).tolist())
    return T



def search_opt_t_path(global_var, y, z, step, data, W, X_m_init_vect_list, visited=None):

    curr_y, curr_z = y, z

    if visited is None:
        visited = dict()

        tpm, ty_bar, tz_bar = get_convergence_values(global_var, data, W, X_m_init_vect_list, [curr_y], [curr_z], False)[0,0]
        visited[(curr_y, curr_z)] = (tpm if tpm else global_var["T_PM"]), int(tpm*(1+ty_bar+tz_bar))

    print(f"{(curr_y, curr_z)} => {visited[(curr_y, curr_z)]}")

    sides = [(curr_y-step, curr_z-step), (curr_y-step, curr_z), (curr_y, curr_z-step)] + [(curr_y-step, curr_z+step), (curr_y+step, curr_z-step)] + [(curr_y+step, curr_z+step), (curr_y, curr_z+step), (curr_y+step, curr_z)]
    sides = [side for side in sides if all(t >= 0 for t in side)]
    for side_y, side_z in sides:
        if (side_y, side_z) not in visited:
            tpm, ty_bar, tz_bar = get_convergence_values(global_var, data, W, X_m_init_vect_list, [side_y], [side_z], False)[0,0]
            visited[(side_y, side_z)] = (tpm if tpm else global_var["T_PM"]), int(tpm*(1+ty_bar+tz_bar))
            print(f"\t{(side_y, side_z)} => {visited[(side_y, side_z)]}")

            if visited[(side_y, side_z)][1] != 0 and visited[(side_y, side_z)][1] < visited[(curr_y, curr_z)][1]:
                break

    min_y, min_z = min((k for k in visited if visited[k][1] != 0), key=lambda k: visited[k][1])
    while (curr_y, curr_z) != (min_y, min_z):

        curr_y, curr_z = min_y, min_z
        print(f"\n{(curr_y, curr_z)} => {visited[(curr_y, curr_z)]}")

        sides = [(curr_y-step, curr_z-step), (curr_y-step, curr_z), (curr_y, curr_z-step)] + [(curr_y-step, curr_z+step), (curr_y+step, curr_z-step)] + [(curr_y+step, curr_z+step), (curr_y, curr_z+step), (curr_y+step, curr_z)]
        sides = [side for side in sides if all(t >= 0 for t in side)]
        for side_y, side_z in sides:
            if (side_y, side_z) not in visited:
                tpm, ty_bar, tz_bar = get_convergence_values(global_var, data, W, X_m_init_vect_list, [side_y], [side_z], False)[0,0]
                visited[(side_y, side_z)] = (tpm if tpm else global_var["T_PM"]), int(tpm*(1+ty_bar+tz_bar))
                print(f"\t{(side_y, side_z)} => {visited[(side_y, side_z)]}")

                if visited[(side_y, side_z)][1] != 0 and visited[(side_y, side_z)][1] < visited[(curr_y, curr_z)][1]:
                    break

        min_y, min_z = min((k for k in visited if visited[k][1] != 0), key=lambda k: visited[k][1])

    return visited, curr_y, curr_z



def large_search_opt_t_path(global_var, y, z, step_list, data, W, X_m_init_vect_list):

    curr_y, curr_z = y, z
    visited = None

    for step in step_list:
        print(f"\nStep: {step}\n")
        visited, curr_y, curr_z = search_opt_t_path(global_var, curr_y, curr_z, step, data, W, X_m_init_vect_list, visited)

    return visited, curr_y, curr_z
        



